import * as C from './creation.js';
import {BlueprintView} from './creation-view.js';
import {measure} from './rehearsal.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const option=(values,current)=>values.map(v=>`<option value="${escape(v)}" ${v===current?'selected':''}>${escape(v)}</option>`).join('');
const number=(id,label,value,min,max,step=1)=>`<label class="creator-field">${label}<input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
const select=(id,label,values,current)=>`<label class="creator-field">${label}<select id="${id}">${option(values,current)}</select></label>`;
const download=(name,data)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};

export class CreationStudio {
 constructor(root,hooks){
  this.root=root;this.hooks=hooks;this.draft=C.seed();this.selected=0;this.tab='form';this.undo=[];this.redo=[];this.results=[];this.opened=false;
  root.innerHTML=`<header class="creator-top"><div><p class="eyebrow">AWE · THE DREAM FOUNDRY</p><h1>Give your imagination a life.</h1></div><div class="creator-actions"><button id="creator-undo" class="button subtle">Undo</button><button id="creator-redo" class="button subtle">Redo</button><button id="creator-close" class="button subtle">Return to world ×</button></div></header>
   <div class="creator-layout"><aside class="creator-left"><label class="creator-field">Creation name<input id="creator-name" maxlength="64"></label><div class="creator-new"><label class="creator-field">Begin a new creation<select id="creator-kind">${option(C.KINDS,'creature')}</select></label><button id="creator-new" class="button subtle">New design</button></div><nav class="creator-tabs" aria-label="Creation tools"><button data-creator-tab="form">Shape</button><button data-creator-tab="behavior">Behavior</button><button data-creator-tab="shelf">Blueprints</button><button data-creator-tab="memory">Experiments</button></nav><div id="creator-inspector"></div></aside>
   <section class="creator-stage" aria-label="Live creation preview"><canvas id="creator-canvas" aria-label="3D model preview. Drag to orbit, scroll to zoom."></canvas><div class="creator-stage-label"><span id="creator-kind-label">CREATURE</span><strong id="creator-preview-name"></strong><small>Drag to orbit · scroll to look closer</small></div><div id="creator-sketch-wrap" hidden><div class="row"><strong>Draw a silhouette</strong><label><input id="creator-mirror" type="checkbox" checked> Mirror strokes</label><button id="creator-sketch-close" class="button subtle">Done drawing</button></div><canvas id="creator-sketch" width="400" height="300" aria-label="Draw to add three-dimensional parts"></canvas><p>Each stroke places a real 3D part. The same form appears in the world.</p></div></section>
   <aside class="creator-right"><p class="eyebrow">SHAPE & BEHAVIOR, TOGETHER</p><div id="creator-explanation"></div><div id="creator-stats"></div><div id="creator-status" role="status" aria-live="polite"></div><div class="creator-primary-actions"><button id="creator-rehearse" class="button primary">Enter a living rehearsal ↗</button><button id="creator-measure" class="button subtle">Run a controlled experiment</button><button id="creator-save" class="button subtle">Save this blueprint</button><button id="creator-place" class="button primary">Bring it into the world ↗</button></div><div id="creator-cost"></div><p class="creator-footnote">Rehearsals use disposable materials. Only an accepted placement spends your world inventory. Imported blueprints contain data, never executable code.</p><a href="./vision.html" target="_blank" rel="noopener">The whole-game design & evidence ↗</a></aside></div>`;
  this.$=id=>root.querySelector('#'+id);
  this.view=new BlueprintView(this.$('creator-canvas'));
  this.$('creator-close').onclick=()=>this.close();
  this.$('creator-name').oninput=e=>this.edit(b=>b.name=e.target.value,false);
  this.$('creator-new').onclick=()=>{this.push();this.draft=C.seed(this.$('creator-kind').value);this.selected=0;this.tab='form';this.refresh();};
  this.$('creator-undo').onclick=()=>{if(this.undo.length){this.redo.push(structuredClone(this.draft));this.draft=this.undo.pop();this.selected=0;this.refresh();}};
  this.$('creator-redo').onclick=()=>{if(this.redo.length){this.undo.push(structuredClone(this.draft));this.draft=this.redo.pop();this.selected=0;this.refresh();}};
  root.querySelectorAll('[data-creator-tab]').forEach(b=>b.onclick=()=>{this.tab=b.dataset.creatorTab;this.refresh();});
  this.$('creator-save').onclick=()=>this.safe(()=>{const saved=this.hooks.save(C.compile(this.draft).blueprint);if(saved)this.draft=structuredClone(saved);this.status('Blueprint saved. Existing world instances keep their original design.');this.sync();});
  this.$('creator-place').onclick=()=>this.safe(()=>{const b=C.compile(this.draft).blueprint;this.hooks.place(b);});
  this.$('creator-rehearse').onclick=()=>this.safe(()=>this.hooks.rehearse(C.compile(this.draft).blueprint));
  this.$('creator-measure').onclick=()=>this.safe(()=>{const result=measure(this.draft);this.results.push(result);if(this.results.length>20)this.results.shift();this.hooks.experiment(result);this.tab='memory';this.refresh();this.status('Experiment complete. These are simulated outcomes, not human playtest scores.');});
  this.$('creator-sketch-close').onclick=()=>this.$('creator-sketch-wrap').hidden=true;
  const sketch=this.$('creator-sketch');let drawing=false,last=null;
  const draw=e=>{if(!drawing)return;const rect=sketch.getBoundingClientRect(),x=Math.round(((e.clientX-rect.left)/rect.width-.5)*12)/2,y=Math.round((1-(e.clientY-rect.top)/rect.height)*10)/2;if(x<-3||x>3||y<.25||y>5)return;if(last&&last.x===x&&last.y===y)return;last={x,y};const points=this.$('creator-mirror').checked&&x!==0?[x,-x]:[x];this.edit(b=>{for(const px of points)if(b.parts.length<32&&!b.parts.some(p=>p.x===px&&p.y===y&&p.z===0))b.parts.push({shape:'orb',x:px,y,z:0,w:.55,h:.55,d:.55,color:'#62decb',role:'ornament',yaw:0});},false);this.sketch();};
  sketch.onpointerdown=e=>{drawing=true;last=null;this.push();sketch.setPointerCapture(e.pointerId);draw(e);};sketch.onpointermove=draw;sketch.onpointerup=()=>{drawing=false;this.refresh();};sketch.onpointercancel=()=>drawing=false;
 }
 push(){this.undo.push(structuredClone(this.draft));if(this.undo.length>40)this.undo.shift();this.redo=[];}
 edit(fn,refresh=true){this.push();fn(this.draft);if(refresh)this.refresh();else this.sync();}
 safe(fn){try{return fn();}catch(e){this.status(e.message,true);return null;}}
 status(text,bad=false){const el=this.$('creator-status');el.textContent=text;el.classList.toggle('invalid',bad);}
 open(blueprint=null){if(blueprint){this.draft=structuredClone(blueprint);this.selected=0;}this.opened=true;this.root.hidden=false;this.view.visible=true;this.refresh();this.$('creator-name').focus();}
 close(){this.opened=false;this.root.hidden=true;this.view.visible=false;this.hooks.close();}
 sync(){
  this.$('creator-preview-name').textContent=this.draft.name;this.$('creator-kind-label').textContent=this.draft.kind.toUpperCase();
  try{const d=C.compile(this.draft),s=this.hooks.world();this.view.set(d.blueprint,this.selected);this.$('creator-status').classList.remove('invalid');this.$('creator-status').textContent='Valid blueprint · '+d.blueprint.parts.length+'/32 parts';
   const facts=d.blueprint.kind==='relic'?[['Impact / healing',d.move.damage],['Reach',d.move.reach+' steps'],['Startup / recovery',d.move.startup+' / '+d.move.recovery+' frames'],['Breath cost',d.move.cost]]:d.blueprint.kind==='creature'?[['Power / reach / tempo',`${d.blueprint.power} / ${d.blueprint.reach} / ${d.blueprint.tempo}`],['Movement',d.creatureSpeed.toFixed(1)+' steps / second'],['Action energy',d.energyCost],['Food', '1 food → 80 energy']]:d.blueprint.kind==='instrument'?[['Score',d.blueprint.score.length+' spatial notes'],['Beat',d.blueprint.beat+' / 60 second'],['Voice',d.blueprint.voice],['Performance','40 Breath · 12s recovery']]:d.blueprint.kind==='trial'?[['Sigils',d.blueprint.course.length],['Order',d.blueprint.order],['Time limit',d.blueprint.seconds+' seconds'],['Rewards','Personal record only']]:[['Walking decks',d.blueprint.parts.filter(p=>p.role==='walkway').length],['Solid parts',d.blueprint.parts.filter(p=>p.role==='solid').length],['Material volume',d.volume.toFixed(2)],['Reclaim','Actual invested materials']];
   this.$('creator-stats').innerHTML='<dl>'+facts.map(([k,v])=>`<div><dt>${k}</dt><dd>${escape(v)}</dd></div>`).join('')+'</dl>';
   this.$('creator-cost').innerHTML='<h3>Its place in the economy</h3>'+C.GOODS.filter(k=>d.cost[k]).map(k=>`<div class="creator-bill ${s.pack[k]<d.cost[k]?'short':''}"><span>${k}</span><b>${d.cost[k]} needed · ${s.pack[k]} held</b></div>`).join('');
  }catch(e){this.status(e.message,true);}
 }
 refresh(){
  const focused=this.root.contains(document.activeElement)?document.activeElement.id:null,selectedSigil=this.$('course-selected')?.value;
  this.$('creator-name').value=this.draft.name;this.$('creator-kind').value=this.draft.kind;
  this.root.querySelectorAll('[data-creator-tab]').forEach(b=>{b.classList.toggle('selected',b.dataset.creatorTab===this.tab);b.setAttribute('aria-pressed',String(b.dataset.creatorTab===this.tab));});
  this.$('creator-explanation').innerHTML={creature:'<h2>A form with intentions.</h2><p>Order its rules. It can follow, defend, orbit, or carry a real gathered resource to you. Food powers its work.</p>',relic:'<h2>An ability you authored.</h2><p>Power, reach and tempo share twelve points. Attune to the finished relic, then press <kbd>T</kbd> to use its actual move.</p>',structure:'<h2>A new possibility in space.</h2><p>Walking decks support bodies. Solid boxes block movement and shots. Light and ornament give the structure its character.</p>',instrument:'<h2>A score with an address.</h2><p>Each note becomes an expanding wave in the world. Healing, protection or force arrives when that wave reaches a body.</p>',trial:'<h2>A game inside your game.</h2><p>Arrange sigils, choose their order and set the clock. Your creation becomes a gate into that playable challenge.</p>'}[this.draft.kind];
  if(this.tab==='form')this.form();if(this.tab==='behavior')this.behavior();if(this.tab==='shelf')this.shelf();if(this.tab==='memory')this.memory();this.sync();if(selectedSigil!==undefined&&this.$('course-selected')){const el=this.$('course-selected');el.value=String(Math.min(Number(selectedSigil),this.draft.course.length-1));el.onchange?.();}if(focused)this.$(focused)?.focus();
 }
 form(){
  const b=this.draft;this.selected=Math.min(this.selected,b.parts.length-1);const p=b.parts[this.selected];
  this.$('creator-inspector').innerHTML=`<div class="creator-part-actions"><button id="creator-add" class="button subtle">Add a part</button><button id="creator-draw" class="button subtle">Draw a silhouette</button><button id="creator-clear" class="button subtle">Start with one part</button></div><label class="creator-field">Part<select id="creator-part">${b.parts.map((p,i)=>`<option value="${i}" ${i===this.selected?'selected':''}>${i+1} · ${p.shape} · ${p.role}</option>`).join('')}</select></label>${p?select('part-shape','Shape',C.SHAPES,p.shape)+select('part-role','Role',b.kind==='structure'?C.ROLES:['ornament','light'],p.role)+`<div class="creator-grid">${number('part-x','Across · X',p.x,-8,8,.1)}${number('part-y','Height · Y',p.y,0,8,.1)}${number('part-z','Depth · Z',p.z,-8,8,.1)}</div><div class="creator-grid">${number('part-w','Width',p.w,.05,8,.05)}${number('part-h','Height',p.h,.05,8,.05)}${number('part-d','Depth',p.d,.05,8,.05)}</div>${number('part-yaw','Rotation',p.yaw,-180,180,5)}<label class="creator-field">Color<input id="part-color" type="color" value="${p.color}"></label><div class="row"><button id="part-copy" class="button subtle">Duplicate</button><button id="part-remove" class="button subtle">Remove</button></div>`:''}<p class="creator-footnote">The preview uses the same geometry as your final object. Collision roles use boxes; walking decks stay at the world surface.</p>`;
  this.$('creator-part').onchange=e=>{this.selected=Number(e.target.value);this.refresh();};
  this.$('creator-add').onclick=()=>this.safe(()=>this.edit(b=>{if(b.parts.length>=32)throw Error('The part budget is full.');b.parts.push({shape:'orb',x:0,y:1,z:0,w:.7,h:.7,d:.7,color:'#8d9cff',role:'ornament',yaw:0});this.selected=b.parts.length-1;}));
  this.$('creator-clear').onclick=()=>this.edit(b=>{b.parts=[{shape:'orb',x:0,y:1,z:0,w:.5,h:.5,d:.5,color:'#62decb',role:'ornament',yaw:0}];this.selected=0;});
  this.$('creator-draw').onclick=()=>{this.$('creator-sketch-wrap').hidden=false;this.sketch();};
  if(!p)return;
  for(const key of ['shape','role','x','y','z','w','h','d','yaw','color'])this.$('part-'+key).onchange=e=>this.safe(()=>this.edit(b=>{const part=b.parts[this.selected];part[key]=['shape','role','color'].includes(key)?e.target.value:Number(e.target.value);if(part.role==='walkway'){part.shape='box';part.h=Math.min(.32,part.h);part.y=.16-part.h/2;}}));
  this.$('part-copy').onclick=()=>this.safe(()=>this.edit(b=>{if(b.parts.length>=32)throw Error('The part budget is full.');const copy=structuredClone(p);copy.x=Math.min(8,copy.x+.5);b.parts.push(copy);this.selected=b.parts.length-1;}));
  this.$('part-remove').onclick=()=>this.safe(()=>this.edit(b=>{if(b.parts.length===1)throw Error('Keep one part, or reshape it.');b.parts.splice(this.selected,1);this.selected=Math.max(0,this.selected-1);}));
 }
 sketch(){const canvas=this.$('creator-sketch'),ctx=canvas.getContext('2d');ctx.clearRect(0,0,400,300);ctx.strokeStyle='#72aaae33';for(let x=0;x<400;x+=33.33){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,300);ctx.stroke();}for(let y=0;y<300;y+=30){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(400,y);ctx.stroke();}for(const p of this.draft.parts){ctx.fillStyle=p.color;ctx.beginPath();ctx.arc((p.x/6+.5)*400,(1-p.y/5)*300,Math.max(4,p.w*22),0,7);ctx.fill();}}
 behavior(){
  const b=this.draft;let html=select('creator-material','Construction material',C.GOODS.filter(k=>k!=='food'),b.material);
  if(b.kind!=='structure'&&b.kind!=='trial')html+=`<p class="creator-footnote">Twelve points shared. More of one quality leaves less for the others.</p><div class="creator-grid">${number('creator-power','Power',b.power,1,8)}${number('creator-reach','Reach',b.reach,1,8)}${number('creator-tempo','Tempo',b.tempo,1,8)}</div>`;
  if(b.kind==='relic')html+=select('creator-verb','What the ability does',['bolt','wave','mend','ward'],b.verb);
  if(b.kind==='creature')html+=`<h3>First matching rule acts</h3>${b.rules.map((r,i)=>`<div class="creator-rule"><strong>${i+1}</strong>${select('rule-when-'+i,'When',C.TRIGGERS,r.when)}${select('rule-do-'+i,'Do',C.ACTIONS,r.do)}<button data-rule-up="${i}" aria-label="Move rule ${i+1} earlier">↑</button><button data-rule-remove="${i}" aria-label="Remove rule ${i+1}">×</button></div>`).join('')}<button id="creator-rule-add" class="button subtle">Add a rule</button>${select('creator-resource','Harvest resource',['wood','stone','food','herb','ore'],b.resource)}`;
  if(b.kind==='instrument')html+=select('creator-voice','Wave effect',['mend','ward','force'],b.voice)+number('creator-beat','Ticks between notes · 60 = 1 second',b.beat,12,60)+`<h3>Compose eight notes</h3><div class="creator-notes">${b.score.map((n,i)=>number('score-'+i,'Note '+(i+1),n,0,12)).join('')}</div><p class="creator-footnote">Pitch is 220 × 2^(note/12) Hz. This is a fantasy instrument: its healing and force are authored game rules.</p>`;
  if(b.kind==='trial')html+=number('creator-seconds','Time limit · seconds',b.seconds,15,180)+select('creator-order','Collection order',['sequence','any'],b.order)+`<h3>Place the sigils</h3><canvas id="creator-course" width="260" height="260" aria-label="Trial map. Click to move the selected sigil."></canvas><label class="creator-field">Selected sigil<select id="course-selected">${b.course.map((p,i)=>`<option value="${i}">${i+1}</option>`).join('')}</select></label><div class="row"><button id="course-add" class="button subtle">Add sigil</button><button id="course-remove" class="button subtle">Remove last</button></div><div class="creator-grid">${number('course-x','Sigil X',b.course[0].x,-12,12)}${number('course-z','Sigil Z',b.course[0].z,-12,12)}</div><p class="creator-footnote">Click the map or type coordinates to move the selected sigil. Coordinates are relative to the trial clearing.</p>`;
  this.$('creator-inspector').innerHTML=html;
  for(const key of ['material','power','reach','tempo','verb','resource','beat','voice','seconds','order']){const el=this.$('creator-'+key);if(el)el.onchange=e=>this.edit(b=>b[key]=['power','reach','tempo','beat','seconds'].includes(key)?Number(e.target.value):e.target.value);}
  b.rules.forEach((r,i)=>{for(const k of ['when','do']){const el=this.$('rule-'+k+'-'+i);if(el)el.onchange=e=>this.edit(b=>b.rules[i][k]=e.target.value);}});
  this.root.querySelectorAll('[data-rule-up]').forEach(el=>el.onclick=()=>this.edit(b=>{const i=Number(el.dataset.ruleUp);if(i)[b.rules[i-1],b.rules[i]]=[b.rules[i],b.rules[i-1]];}));
  this.root.querySelectorAll('[data-rule-remove]').forEach(el=>el.onclick=()=>this.safe(()=>this.edit(b=>{if(b.rules.length===1)throw Error('Keep at least one behavior rule.');b.rules.splice(Number(el.dataset.ruleRemove),1);})));
  if(this.$('creator-rule-add'))this.$('creator-rule-add').onclick=()=>this.safe(()=>this.edit(b=>{if(b.rules.length===4)throw Error('Four behavior rules is the current budget.');b.rules.push({when:'always',do:'rest'});}));
  b.score.forEach((n,i)=>{const el=this.$('score-'+i);if(el)el.onchange=e=>this.edit(b=>b.score[i]=Number(e.target.value));});
  if(b.kind==='trial'){
   const canvas=this.$('creator-course'),ctx=canvas.getContext('2d');ctx.fillStyle='#091c2d';ctx.fillRect(0,0,260,260);ctx.strokeStyle='#bde2d136';ctx.beginPath();ctx.arc(130,130,125,0,7);ctx.stroke();ctx.strokeStyle='#7dbfb7';ctx.beginPath();b.course.forEach((p,i)=>i?ctx.lineTo(130+p.x*8,130+p.z*8):ctx.moveTo(130+p.x*8,130+p.z*8));ctx.stroke();b.course.forEach((p,i)=>{ctx.fillStyle='#f1d199';ctx.beginPath();ctx.arc(130+p.x*8,130+p.z*8,9,0,7);ctx.fill();ctx.fillStyle='#102934';ctx.font='12px system-ui';ctx.fillText(String(i+1),127+p.x*8,134+p.z*8);});
   this.$('course-selected').onchange=()=>{const p=this.draft.course[Number(this.$('course-selected').value)];this.$('course-x').value=p.x;this.$('course-z').value=p.z;};
   for(const axis of ['x','z'])this.$('course-'+axis).onchange=e=>{const i=Number(this.$('course-selected').value);this.edit(b=>b.course[i][axis]=Number(e.target.value));};
   canvas.onclick=e=>{const rect=canvas.getBoundingClientRect(),i=Number(this.$('course-selected').value);this.edit(b=>{b.course[i]={x:Math.max(-12,Math.min(12,Math.round(((e.clientX-rect.left)/rect.width*260-130)/8))),z:Math.max(-12,Math.min(12,Math.round(((e.clientY-rect.top)/rect.height*260-130)/8)))};});};
   this.$('course-add').onclick=()=>this.safe(()=>this.edit(b=>{if(b.course.length===12)throw Error('Twelve sigils is the current limit.');b.course.push({x:0,z:0});}));
   this.$('course-remove').onclick=()=>this.safe(()=>this.edit(b=>{if(b.course.length===3)throw Error('Keep three sigils.');b.course.pop();}));
  }
 }
 shelf(){
  const s=this.hooks.world();this.$('creator-inspector').innerHTML=`<div class="row"><button id="blueprint-export" class="button subtle">Export blueprint ↓</button><button id="blueprint-import-button" class="button subtle">Import blueprint ↑</button><input id="blueprint-import" type="file" accept="application/json" hidden></div><p class="creator-footnote">Share the recipe. Each world must supply its own materials to make it real.</p><h3>Your blueprints</h3>${s.creation.drafts.map(b=>`<div class="creator-shelf-item"><strong>${escape(b.name)}</strong><small>${b.kind} · revision ${b.revision}</small><div class="row"><button data-open-blueprint="${escape(b.id)}" class="button subtle">Edit</button><button data-branch-blueprint="${escape(b.id)}" class="button subtle">Create a variation</button><button data-delete-blueprint="${escape(b.id)}" class="button subtle">Remove recipe</button></div></div>`).join('')||'<p>No saved blueprints yet. Save the design you are shaping.</p>'}<h3>Present in your world</h3>${s.creation.instances.map(e=>`<button data-inspect-creation="${escape(e.id)}" class="creator-instance">${escape(e.blueprint.name)}<small>${e.blueprint.kind} · ${e.blueprint.kind==='creature'?escape(e.task):'persistent instance'}</small></button>`).join('')||'<p>No authored instances yet.</p>'}<label class="creator-field creator-agent"><span><input id="creator-agent-grant" type="checkbox" ${s.creation.grants.agent?'checked':''}> Accept local agent blueprint proposals</span></label><p class="creator-footnote">The local authoring API can propose data for your review. It cannot spend resources or publish an instance. No external model is connected.</p>${s.creation.proposals.map((p,i)=>`<button data-review-proposal="${i}" class="creator-instance">Review ${escape(p.name)}</button>`).join('')}`;
  this.$('blueprint-export').onclick=()=>this.safe(()=>download('AWE_Blueprint.json',C.compile(this.draft).blueprint));this.$('blueprint-import-button').onclick=()=>this.$('blueprint-import').click();this.$('blueprint-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('A blueprint file must be smaller than 100 KB.');this.push();this.draft=C.branch(JSON.parse(await file.text()));this.selected=0;this.tab='form';this.refresh();this.status('Imported a recipe variation. No world materials or rewards were imported.');}catch(err){this.status(err.message,true);}};
  this.root.querySelectorAll('[data-open-blueprint]').forEach(el=>el.onclick=()=>{this.push();this.draft=structuredClone(s.creation.drafts.find(b=>b.id===el.dataset.openBlueprint));this.tab='form';this.selected=0;this.refresh();});
  this.root.querySelectorAll('[data-branch-blueprint]').forEach(el=>el.onclick=()=>{this.push();this.draft=C.branch(s.creation.drafts.find(b=>b.id===el.dataset.branchBlueprint));this.tab='form';this.selected=0;this.refresh();});
  this.root.querySelectorAll('[data-delete-blueprint]').forEach(el=>el.onclick=()=>{this.hooks.removeDraft(el.dataset.deleteBlueprint);this.refresh();});
  this.root.querySelectorAll('[data-inspect-creation]').forEach(el=>el.onclick=()=>{this.close();this.hooks.inspect(el.dataset.inspectCreation);});
  this.$('creator-agent-grant').onchange=e=>this.hooks.agentGrant(e.target.checked);
  this.root.querySelectorAll('[data-review-proposal]').forEach(el=>el.onclick=()=>{this.draft=C.branch(s.creation.proposals[Number(el.dataset.reviewProposal)]);this.tab='form';this.refresh();this.status('Review this proposed blueprint. Placement still needs your action and materials.');});
 }
 memory(){
  const recent=this.results.slice(-2);this.$('creator-inspector').innerHTML=`<h3>Keep the useful mistakes</h3><p>Change one quality, run the same experiment, and compare what actually happened.</p>${recent.length?'<div class="creator-comparison">'+recent.map(r=>`<article><h4>${escape(r.name)}</h4><dl>${[['Kind',r.kind],['Method',r.method],['Simulated seconds',(r.ticks/60).toFixed(1)],['First impact',r.firstImpactTick===null?'—':(r.firstImpactTick/60).toFixed(2)+'s'],['Target defeated',r.targetDefeatTick===null?'—':(r.targetDefeatTick/60).toFixed(2)+'s'],['Attacks begun',r.attacksStarted],['Damage',r.damage],['Healing',r.healing],['Delivery count',r.deliveries],['Score notes',r.notes],['Distance walked',r.travel],['Trial result',r.trialResult||'—'],['Reached far bank',r.farBank?'yes':'no'],['Ledger delta',Object.values(r.ledgerDelta).every(n=>n===0)?'balanced':'inspect']].map(([k,v])=>`<div><dt>${k}</dt><dd>${escape(v)}</dd></div>`).join('')}</dl></article>`).join('')+'</div>':'<p>No experiments yet. Run a controlled experiment with this blueprint.</p>'}<button id="creator-results-export" class="button subtle" ${this.results.length?'':'disabled'}>Export experiment evidence ↓</button><p class="creator-footnote">The bench has one 34-health target near the spawn, a closed crossing and normal movement. Damage saturates when that target falls. Compare timing as well as totals. Results retain the exact recipe and are available in this session or an exported evidence file.</p><h3>What your world remembers</h3>${this.hooks.world().creation.memories.slice(-14).reverse().map(m=>`<p class="creator-memory">${escape(m.text)}</p>`).join('')}`;this.$('creator-results-export').onclick=()=>download('AWE_Creation_Experiments.json',{method:'Deterministic local-state policies, not human playtests.',results:this.results});
 }
}
